try {
  const rawAnswer = $input.item.json.answer || "";
  const newDifyConversationId = $input.item.json.conversation_id;
  const webhookData = $('Webhook').first().json;

  // Вырезаем <think> и Markdown
  let cleanText = rawAnswer.replace(/<think>[\s\S]*?<\/think>\n*/g, '').trim();
  cleanText = cleanText.replace(/```json/g, '').replace(/```/g, '').trim();

  const parsedData = JSON.parse(cleanText);
  const contract = parsedData.contract_data || {};

  let isReady = parsedData.is_ready_for_doc === true;
  let replyMessage = parsedData.reply_to_client || "";

  // 1. ЖЕСТКАЯ ВАЛИДАЦИЯ N8N (Ищем пустые поля или "Не указано")
  const required = ['fio', 'position', 'company', 'inn'];
  let missing = [];

  for (let key of required) {
      const val = contract[key];
      if (!val || val.toString().trim() === "" || val.toString().toLowerCase().includes("не указано")) {
          missing.push(key);
      }
  }

  // 2. ГИБРИДНАЯ МАРШРУТИЗАЦИЯ И ПЕРЕХВАТ ОШИБОК ИИ
  if (missing.length > 0) {
      isReady = false; // Принудительно опускаем шлагбаум

      // Бэкенд вмешивается ТОЛЬКО если ИИ галлюцинирует (говорит, что всё готово, хотя данных нет)
      if (replyMessage.includes("формирует") || replyMessage.includes("валидирован") || replyMessage.includes("собраны")) {
          const dict = { 'fio': 'ФИО', 'position': 'Должность', 'company': 'Название компании', 'inn': 'ИНН' };
          const missingRu = missing.map(m => dict[m]).join(', ');

          replyMessage = `Я сохранил переданные данные, но для договора мне всё ещё нужно узнать: ${missingRu}. Пожалуйста, напишите их.`;
      } 
      // Если ИИ написал нормальную просьбу (Сценарий А), мы оставляем его текст нетронутым!
      else if (replyMessage === "") {
          replyMessage = "Пожалуйста, уточните недостающие данные.";
      }

  } else {
      isReady = true; // Принудительно открываем шлюз

      // Страховка: если ИИ забыл сказать победную фразу
      if (!replyMessage.includes("формирует") && !replyMessage.includes("валидирован")) {
          replyMessage = "Данные валидированы. Система формирует договор и техническое задание. Файл появится в чате в течение 2-х минут.";
      }
  }

  return [{
    json: {
      message_to_send: replyMessage,
      document_payload: contract,
      is_ready_for_doc: isReady, // 100% надежный флаг для следующего узла IF
      conversation_id: newDifyConversationId,
      contact_id: webhookData.sender.contact_id
    }
  }];

} catch (error) {
  throw new Error(`[Dify Parser Error] Ошибка обработки данных: ${error.message}`);
}

try {
    const webhookJson = $('Webhook').first().json;

    // БРОНЕБОЙНОЕ ИЗВЛЕЧЕНИЕ ТЕКСТА
    // Пытаемся найти текст в body (если это POST из Postman/внешней системы)
    // или на верхнем уровне (если мы симулируем запуск внутри n8n)
    const payloadObj = webhookJson.body?.payload || webhookJson.payload || {};
    const text = payloadObj.raw_text || "";

    // Ищем любую ссылку в тексте
    const urlRegex = /(https?:\/\/[^\s]+|[a-zA-Z0-9.-]+\.[a-zA-Z]{2,})/g;
    const match = text.match(urlRegex);

    let websiteUrl = match ? match[0] : "";
    if (websiteUrl && !websiteUrl.startsWith('http')) {
        websiteUrl = "https://" + websiteUrl;
    }

    return [{ json: { website_url: websiteUrl } }];

} catch (error) {
    // В случае критического сбоя отдаем пустую ссылку, чтобы не ронять ветку NEW_LEAD
    console.log("Extract URL Error: " + error.message);
    return [{ json: { website_url: "" } }];
}

